		m.MultiBlob = rt.Ld32(m.Mem, 14)
		m.MultiSlots = rt.Ld8(m.Mem, int(m.MultiBlob))
		m.MultiTables = m.MultiBlob + rt.Ld32(m.Mem, int(m.MultiBlob)+4)
		m.SpanReserve = rt.Ld32(m.Mem, int(m.MultiBlob)+8)
		m.SpanCacheMode = 2
