	var after, lineEnd, t0 uint32
	lineEnd = m.MarkdownLineEnd(m.Ptr)
	after = m.MarkdownAfterLine(lineEnd)
	t0 = m.MarkdownQuotePrefix(m.Ptr, lineEnd, quotes)
