	if streamRoot != 0 {
		m.StreamWindow = 46376
		rt.St32(m.Mem, int(m.StreamWindow), line)
		if m.StreamStateLo > 152 {
			m.StreamStateLo = 152
		}
		if m.StreamStateHi < 156 {
			m.StreamStateHi = 156
		}
		m.StreamDepth = 0
	}
