// RstIsAlnum is $rstIsAlnum.
func (m *Machine) RstIsAlnum(c uint32) uint32 {
	return rt.B2u(c >= 128) | (rt.Ld8(m.Mem, int(c)+1936)>>3)&1
}

// RstCloseEnd is $rstCloseEnd.
func (m *Machine) RstCloseEnd(p uint32, stop uint32, c uint32, n uint32, tight uint32) uint32 {
	var q uint32
	for {
		p = m.ScanFindSpecial(p, stop, c, 0, 0)
		if p >= stop {
			return 0
		}
		q = p + n
		if q <= stop && (n == 1 || rt.Ld8(m.Mem, int(p)+1) == c) && m.LexIsSpace(rt.Ld8(m.Mem, int(p-1))) == 0 && (tight == 0 || q >= stop || m.RstIsAlnum(rt.Ld8(m.Mem, int(q))) == 0) {
			return q
		}
		p++
	}
}

// RstTrimEnd is $rstTrimEnd.
func (m *Machine) RstTrimEnd(p uint32, stop uint32) uint32 {
trim:
	for {
		if stop <= p {
			break trim
		}
		if m.LexIsSpace(rt.Ld8(m.Mem, int(stop-1))) == 0 {
			break trim
		}
		stop--
	}
	return stop
}

// RstIsRule is $rstIsRule.
func (m *Machine) RstIsRule(p uint32, stop uint32) uint32 {
	var c, q, gaps uint32
	c = rt.Ld8(m.Mem, int(p))
	if rt.B2u(stop-p < 3)|rt.B2u(c-33 > 93)|m.RstIsAlnum(c) != 0 {
		return 0
	}
	q = p + 1
run:
	for {
		if q >= stop {
			break run
		}
		if rt.Ld8(m.Mem, int(q)) != c {
			if m.LexIsSpace(rt.Ld8(m.Mem, int(q))) == 0 || (c != '=' && c != '-') {
				break run
			}
			gaps = 1
		}
		q++
	}
	return rt.Sel32(q == stop, gaps+1, 0)
}

// RstLinkSuffix is $rstLinkSuffix.
func (m *Machine) RstLinkSuffix(p uint32, stop uint32) uint32 {
	var n uint32
count:
	for {
		if p+n >= stop {
			break count
		}
		if rt.Ld8(m.Mem, int(p+n)) != '_' {
			break count
		}
		n++
		if n >= 2 {
			break
		}
	}
	return n
}

// RstPlainEnd is $rstPlainEnd.
func (m *Machine) RstPlainEnd(p uint32, stop uint32, a uint32, b uint32, c uint32) uint32 {
	var mask uint32
	var w, va, vb, vc rt.V128
	if p >= stop {
		return stop
	}
	va = rt.Splat8(a)
	vb = rt.Splat8(b)
	vc = rt.Splat8(c)
wide:
	for {
		w = rt.LdV(m.Mem, int(p))
		mask = rt.Bitmask8(rt.Or(rt.Or(rt.Or(rt.Eq8(w, rt.Splat8(42)), rt.Eq8(w, rt.Splat8(96))), rt.Or(rt.Eq8(w, rt.Splat8(124)), rt.Eq8(w, rt.Splat8(92)))), rt.Or(rt.Or(rt.Eq8(w, rt.Splat8(58)), rt.Eq8(w, rt.Splat8(95))), rt.Or(rt.Eq8(w, va), rt.Or(rt.Eq8(w, vb), rt.Eq8(w, vc))))))
		if mask != 0 {
			p += rt.Ctz32(mask)
			break wide
		}
		p += 16
		if p >= stop {
			break
		}
	}
	return rt.Sel32(p < stop, p, stop)
}

// RstWordStart is $rstWordStart.
func (m *Machine) RstWordStart(lhs uint32, p uint32) uint32 {
	var c uint32
back:
	for {
		if p <= lhs {
			break back
		}
		c = rt.Ld8(m.Mem, int(p-1))
		if m.LexIsIdentContinue(c)&rt.B2u(c != '$')|rt.B2u(c == '-') == 0 {
			break back
		}
		p--
	}
	return p
}

// HlRst is $hlRst.
