		m.StreamWindow = 46464
		rt.St32(m.Mem, int(m.StreamWindow), argument)
		rt.St32(m.Mem, int(m.StreamWindow)+4, quote)
		rt.St32(m.Mem, int(m.StreamWindow)+8, label)
		rt.St64(m.Mem, int(m.StreamWindow)+16, variables)
