				rt.St32(m.Mem, 98064, streamRoot)
				rt.St32(m.Mem, 98068, state)
				rt.St32(m.Mem, 98072, kind)
				rt.St32(m.Mem, 98076, close_)
				rt.St32(m.Mem, 98080, open)
				m.LiveSuspended = 1
				return
