		m.ScanWhitespace()
		m.EmitGap(gap, m.Ptr)
		if m.Ptr >= m.End {
			break next
		}
		lhs = m.Ptr
		c = rt.Ld8(m.Mem, int(m.Ptr))
		c2 = m.C3Byte(m.Ptr + 1)
		c3 = m.C3Byte(m.Ptr + 2)
