// CmakeBracketEquals is $cmakeBracketEquals.
func (m *Machine) CmakeBracketEquals(p uint32) uint32 {
	var n uint32
	p++
l:
	for {
		if m.CmakeByte(p) != '=' {
			break l
		}
		p++
		n++
	}
	if m.CmakeByte(p) != '[' || n > 30 {
		return 0xffffffff
	}
	return n
}

// CmakeBracketBody is $cmakeBracketBody.
func (m *Machine) CmakeBracketBody(n uint32, hl uint32) {
	var lhs uint32
	lhs = m.Ptr
	m.Ptr += n + 2
	m.EmitTok(hl, lhs, m.Ptr)
	rt.St8(m.Mem, 13952, 93)
	rt.Fill(m.Mem, 13953, 61, n)
	rt.St8(m.Mem, int(13953+n), 93)
	m.StreamA = n + 2
	m.StreamHl = hl
	if m.StreamResumeFixed() != 0 {
		m.StreamSetFixed(13952, n+2, hl)
	} else {
		m.StreamA = 0
		m.StreamHl = 0
	}
}

// CmakeIsRefOpen is $cmakeIsRefOpen.
