				rt.St32(m.Mem, 98068, lineHead)
				rt.St32(m.Mem, 98072, mode)
				rt.St32(m.Mem, 98076, targets)
				rt.St32(m.Mem, 98080, expectVar)
				rt.St32(m.Mem, 98084, cmdHead)
				rt.St32(m.Mem, 98088, inRule)
				rt.St32(m.Mem, 98092, define)
