		if c|32 == 120 {
			return m.ScanHexRun(p+2, 2)
		}
		if c|32 == 117 {
			q = p + 2
			if m.TemplateByte(q) != '{' {
				return m.ScanHexRun(q, 4)
			}
			q = m.ScanHexRun(q+1, 8)
			return rt.Sel32(m.TemplateByte(q) == '}', q+1, q)
		}
		if m.LexIsDigit(c) != 0 {
			q = p + 2
		digits:
			for {
				if m.LexIsDigit(m.TemplateByte(q)) == 0 {
					break digits
				}
				q++
			}
			return q
		}
