// ObjcWordHl is $objcWordHl.
func (m *Machine) ObjcWordHl(lhs uint32, rhs uint32, at uint32, propAttrs uint32) uint32 {
	var g, n uint32
	n = m.LexKeywordValue(lhs, rhs, 23328, 31, 76)
	g = n >> 8
	if at != 0 {
		n = rhs - lhs
		if g == 1 {
			if (n == 9 && rt.Ld64(m.Mem, int(lhs)) == 0x6361667265746e69) || (n == 14 && rt.Ld64(m.Mem, int(lhs)) == 0x6e656d656c706d69) || (n == 8 && rt.Ld64(m.Mem, int(lhs)) == 0x6c6f636f746f7270) || (n == 5 && rt.Ld32(m.Mem, int(lhs)) == 0x73616c63) {
				return 273
			}
			if n == 8 && rt.Ld64(m.Mem, int(lhs)) == 0x79747265706f7270 {
				return 529
			}
		}
		return TokenKeyword
	}
	if g == 1 || g > 6 || (g == 6 && propAttrs == 0) {
		return 0xffffffff
	}
	return n & 255
}

// HlObjc is $hlObjc.
