					m.Ptr = m.IndentAfterBreak(lineEnd)
					m.EmitGap(lineEnd, m.Ptr)
					if kind != 0 {
						if kind == 2048 {
							block = 129 | indent<<8
						} else {
							kind &= 255
							if kind != 0 {
								m.IndentBody(kind, indent, 0)
							} else {
								block = 130 | indent<<8
							}
						}
					}
					continue line
