	for {
		if m_ == 0 {
			break strip
		}
		if m.LexIsDigit(rt.Ld8(m.Mem, int(1359+m_))) == 0 {
			break strip
		}
		m_--
	}
	if m_ < n && ((m_ == 5 && w&0xffffffffff == 0x656c746974) || (m_ == 8 && w == 0x65746f6e746f6f66)) {
		return TokenKeyword
	}
	return 0xffffffff
